-- Classic 1.60: battleground event spawns as spawn groups (VMaNGOS battleground_events / creature_battleground /
-- gameobject_battleground). Before this every node state of Alterac Valley was spawned at once (both mine owners,
-- every defender tier, burning towers next to intact ones) and the Arathi Basin node creatures were always up.
-- Generated by classic_re/classic_bg_spawn_groups.py. Spawn guids are the VMaNGOS guids (creature + 20000000,
-- gameobject + 30000000).
--
-- Alterac Valley: group 300000 + event1 * 10 + event2. Flag 0 = state active when the battle is created (VMaNGOS Reset),
-- flag 4 = manual, switched by battleground_classic_alterac_valley. Doors (event 254) stay static.
-- Arathi Basin: node creatures join the banner groups 529000 + node * 10 + state of 2026_10_11_41.
-- Warsong Gulch: 489004 spirit guides, spawned when the battle starts.

-- Alterac Valley
DELETE FROM `spawn_group` WHERE `groupId` BETWEEN 300000 AND 302999;
DELETE FROM `spawn_group_template` WHERE `groupId` BETWEEN 300000 AND 302999;

-- Arathi Basin node creatures (spirit guides, node NPCs) join the node state groups
