-- Alterac Valley: the retail script needs the retail per node banner entries and world state spawn group conditions;
-- map 30 has the vanilla banners (one entry for every graveyard), so the classic script drives it like VMaNGOS.
DELETE FROM `battleground_scripts` WHERE `MapId` = 30 AND `BattlemasterListId` = 0;
UPDATE `gameobject_template` SET `ScriptName` = 'go_classic_av_banner' WHERE `entry` IN (178364,178365,178925,178940,178943,179286,179287,179435,180418);

-- Alterac Valley graveyards follow the node owner (VMaNGOS GetClosestGraveYard: owned and controlled nodes),
-- world states set by the classic script. Main graveyards 610 / 611 stay team only (2026_10_11_07).
-- Frostwolf Graveyard 690 was missing from graveyard_zone (VMaNGOS picks AV graveyards in code, not by zone).
DELETE FROM `graveyard_zone` WHERE `ID` = 690 AND `GhostZone` = 2597;
DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId` = 27 AND `SourceGroup` = 2597 AND `SourceEntry` IN (169,689,690,729,749,750,751);
